// Regenerates server/helper-source.ts from server/git-credential-helper.mjs (the daemon bundles the server entry, so the
// plugin cannot rely on the .mjs sitting next to it). A test fails when the two differ.   node .github/scripts/embed-helper.mjs
import { readFileSync, writeFileSync } from "node:fs";

const source = readFileSync(new URL("../../server/git-credential-helper.mjs", import.meta.url), "utf8");
const out = `// Generated by .github/scripts/embed-helper.mjs from git-credential-helper.mjs. Do not edit by hand.
export const HELPER_SOURCE: string = ${JSON.stringify(source)};
`;
writeFileSync(new URL("../../server/helper-source.ts", import.meta.url), out);
